{"path": "src/mongoose.js", "content": "require('dotenv').config();
const mongoose = require('mongoose');

const uri = process.env.DOCUMENTDB_URI;
if (!uri) {
  throw new Error('DOCUMENTDB_URI environment variable is required');
}

// Use the database name explicitly per sample guidance
const DB_NAME = 'sample_retail_10';

let isConnected = false;

async function connect() {
  if (isConnected) return mongoose;
  // Use sensible defaults; leave pool tuning to the user.
  await mongoose.connect(uri, { dbName: DB_NAME, autoIndex: false });
  isConnected = true;
  return mongoose;
}

async function disconnect() {
  if (!isConnected) return;
  await mongoose.disconnect();
  isConnected = false;
}

module.exports = { connect, disconnect, mongoose };
"}

{"path": "src/models/tenantSafetyPlugin.js", "content": "// A small plugin that ensures tenantId is present for writes and queries
module.exports = function tenantSafetyPlugin(schema) {
  // For save operations ensure tenantId exists
  schema.pre('save', function (next) {
    if (!this.tenantId) return next(new Error('tenantId is required'));
    next();
  });

  // For query middleware, check that a tenantId is part of the filter
  function ensureTenant(next) {
    const q = this.getQuery();
    if (!q || !Object.prototype.hasOwnProperty.call(q, 'tenantId')) {
      return next(new Error('Repository-safety: tenantId must be present in query filter'));
    }
    next();
  }

  schema.pre('find', ensureTenant);
  schema.pre('findOne', ensureTenant);
  schema.pre('updateOne', ensureTenant);
  schema.pre('findOneAndUpdate', ensureTenant);
  schema.pre('deleteOne', ensureTenant);
};
"}

{"path": "src/models/product.js", "content": "const { Schema } = require('mongoose');
const tenantSafetyPlugin = require('./tenantSafetyPlugin');

const ProductSchema = new Schema({
  tenantId: { type: String, required: true, index: true },
  sku: { type: String, required: true },
  name: { type: String, required: true },
  description: String,
  price: Number,
  createdAt: { type: Date, default: () => new Date() }
});

ProductSchema.plugin(tenantSafetyPlugin);
// compound index: (tenantId, sku) unique per tenant
ProductSchema.index({ tenantId: 1, sku: 1 }, { unique: true });

module.exports = ProductSchema;
"}

