{"path": "src/repos/productRepo.js", "content": "class ProductRepo {
  constructor(models, tenantId) {
    if (!tenantId) throw new Error('tenantId is required to create a repository');
    this.tenantId = tenantId;
    this.Product = models.Product;
  }

  async createOrUpdate(product) {
    // ensure tenantId cannot be overridden
    product.tenantId = this.tenantId;
    const filter = { tenantId: this.tenantId, sku: product.sku };
    return this.Product.findOneAndUpdate(filter, product, { upsert: true, new: true, setDefaultsOnInsert: true });
  }

  async findBySku(sku) {
    return this.Product.findOne({ tenantId: this.tenantId, sku }).lean();
  }

  async listAll() {
    return this.Product.find({ tenantId: this.tenantId }).lean();
  }
}

module.exports = ProductRepo;
"}

{"path": "src/repos/inventoryRepo.js", "content": "class InventoryRepo {
  constructor(models, tenantId) {
    if (!tenantId) throw new Error('tenantId is required to create a repository');
    this.tenantId = tenantId;
    this.Inventory = models.Inventory;
  }

  async upsertInventory(sku, quantity) {
    const filter = { tenantId: this.tenantId, sku };
    const update = { $set: { quantity, updatedAt: new Date() }, $setOnInsert: { tenantId: this.tenantId, sku } };
    return this.Inventory.updateOne(filter, update, { upsert: true });
  }

  async getInventory(sku) {
    return this.Inventory.findOne({ tenantId: this.tenantId, sku }).lean();
  }
}

module.exports = InventoryRepo;
"}

{"path": "src/repos/orderRepo.js", "content": "class OrderRepo {
  constructor(models, tenantId) {
    if (!tenantId) throw new Error('tenantId is required to create a repository');
    this.tenantId = tenantId;
    this.Order = models.Order;
  }

  async createOrder(order) {
    order.tenantId = this.tenantId;
    order.createdAt = order.createdAt || new Date();
    return this.Order.create(order);
  }

  async listRecent(limit = 10) {
    return this.Order.find({ tenantId: this.tenantId }).sort({ createdAt: -1 }).limit(limit).lean();
  }
}

module.exports = OrderRepo;
"}

